  const c_ben_1 = await ui.claimAt(pg_uma, p_ben, 1);
  const c_ben_2 = await ui.claimAt(pg_uma, p_ben, 2);
  const c_ben_3 = await ui.claimAt(pg_uma, p_ben, 3);
  const c_ben_4 = await ui.claimAt(pg_uma, p_ben, 4);
  expect(await ui.claimAction(pg_uma, c_ben_2, "open")).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.delegate(pg_wes, {"user": "uma", "from": "2026-03-15", "to": "2026-04-02"})).toBe(true);
  await ui.refresh(pg_uma);
  await ui.refresh(pg_wes);
  expect(await ui.unstate(pg_wes, p_ada)).toBe(true);
  expect(await ui.claimAction(pg_wes, c_ben_2, "settle", "2026-02-10")).toBe(false);
  await ui.refresh(pg_wes);

