        value={deferTo}
        onChange={(e) => {
          setDeferTo(e.target.value);
          setError('');
        }}
      />
      <button
        type="button"
        data-testid="claim-defer"
        disabled={defer.isPending}
        onClick={() => {
          setError('');
          const until = deferTo.trim();
          if (!/^\d{4}-\d{2}-\d{2}$/.test(until)) {
            setError('Type the date to defer the claim until as yyyy-mm-dd.');
            return;
